WITH cleaned AS (SELECT *, cost * price AS margin, INITCAP(TRIM(brand)) AS brand_title, COALESCE(brand, 'OTHER') AS brand_clean FROM products WHERE product_name IS NOT NULL AND brand IS DISTINCT FROM 'Acme') SELECT DATE_TRUNC('MONTH', launch_date) AS activity_month, CORR(price, cost) AS corr_price_cost, MAX(stock_qty) FILTER (WHERE brand = 'Umbrella') AS umbrella_max_stock_qty, COUNT_IF(brand = 'Initech') AS initech_events FROM cleaned GROUP BY DATE_TRUNC('MONTH', launch_date) ORDER BY initech_events
